## C++

```cpp
#include <iostream>
#include <vector>
using namespace std;
typedef long long ll;
const ll MOD = 998244353;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> a(n);
    // 读取数组
    for(int i = 0; i < n; i++){
        cin >> a[i];
    }

    // 计算数组所有元素之和 S
    ll S = 0;
    for(int i = 0; i < n; i++){
        S += a[i];
    }

    ll prefix = 0;
    ll ans = 0;
    // 枚举分割位置 x，x 的取值范围为 1 到 n-1
    for(int x = 0; x < n - 1; x++){
        prefix += a[x];         // 前缀和 pre = ∑(a[0]..a[x])
        ll suffix = S - prefix;   // 后缀和 = S - pre
        ll product = prefix * suffix;  // 计算表达式值
        if(product > ans)
            ans = product;
    }

    // 输出答案，对 MOD 取模
    cout << ans % MOD << "\n";
    return 0;
}
```

