import sys

MOD = 998244353

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    p = list(map(int, data[1:1+n]))

    S = sum(p)
    prefix = 0
    ans = 0
    # 枚举分割位置 k，对应索引从 0 到 n-2
    for i in range(n - 1):
        prefix += p[i]
        suffix = S - prefix
        product = prefix * suffix
        if product > ans:
            ans = product

    print(ans % MOD)

if __name__ == "__main__":
    main()
